// Generated by scripts/agent_catalog_contract.py from the agent's pinned
// published schema and the agent service's own changes to it; do not edit.
// Regenerate with `node scripts/agent-catalog-contract.mjs`; `--check` fails
// when it is stale.

/**
 * Completed-turn admission evidence for an execution lane.
 *
 * `UNPROVEN` is a lane served without a recorded completed turn for the
 * installed runtime. Whether a lane in that position is served at all is the
 * deployment's proof policy; this type only names the outcome.
 */
export type AdmissionState =
  "admitted" | "unproven" | "not_admitted" | "unknown";

/**
 * One file of a Hugging Face repository, pinned by digest and size.
 *
 * Attributes: file: The file's name at the repository's root: a plain name
 * ending in `.gguf`. sha256: The SHA-256 of the file's bytes, as lowercase
 * hex. size_bytes: The file's size in bytes; positive and at most 2**64 - 1.
 */
export type ArtefactFile = {
  file: string;
  sha256: string;
  size_bytes: number;
};

/**
 * What a host supplies for a lane to authenticate.
 *
 * Values: API_KEY: A key, carried in the credential frame under the lane's
 * `agent_credential_id`. The lane has a declared endpoint; a `base_url` handed
 * with the key replaces it. API_KEY_WITH_BASE_URL: A key and the vendor
 * endpoint it is valid for. `default_base_url` is the endpoint used when none
 * is handed; when it is null an endpoint must be handed with the key.
 * PROVIDER_SIGN_IN_ONLY: Nothing. The lane's program authenticates from its
 * own sign-in, and the credential frame carries nothing for it. NONE: Nothing.
 * The lane reaches an unauthenticated server on this computer; the credential
 * frame carries nothing for it.
 */
export type AuthKind =
  "api_key" | "api_key_with_base_url" | "provider_sign_in_only" | "none";

/**
 * Authentication evidence, separate from configuration presence.
 */
export type AuthenticationState =
  "authenticated" | "unauthenticated" | "unknown" | "not_applicable";

/**
 * One kind of content a background request's user turn carries.
 */
export type BackgroundInput = "text" | "image" | "pdf";

export type BackgroundInputState =
  "unsupported" | "unproven" | "unproven_version" | "proven";

/**
 * One reply option of a background request, named as its request member is.
 */
export type BackgroundOption =
  "temperature" | "context_tokens" | "response_schema";

/**
 * How a lane takes each input a host's background request carries.
 *
 * `unsupported`: the lane cannot run a background request, or its transport
 * carries no such input, and a request carrying one is refused with
 * `input_not_supported`. Otherwise how far a live background request has
 * proven it on this host: `proven`, `unproven_version` or `unproven`.
 */
export type BackgroundRequestSupportResponse = {
  text: BackgroundInputState;
  image: BackgroundInputState;
  pdf: BackgroundInputState;
  options: BackgroundOption[];
  /**
   * Whether a background request on the lane may carry an image.
   */
  accepts_images: boolean;
  /**
   * Whether a background request on the lane may carry a PDF.
   */
  accepts_pdfs: boolean;
};

/**
 * How far one capability had been proven on a lane, as this host found it.
 *
 * `entry` names the tool-server entry the state is for. It is given exactly
 * for tool access and writing, the capabilities proven together with an entry.
 * `generation` names the models' multi-agent generation the state is for,
 * where the lane's proof covers some generations only; a frozen selection
 * keeps the state of its own model's generation.
 */
export type CapabilityProof = {
  capability: LaneCapability;
  entry?: string | null;
  generation?: MultiAgentGeneration | null;
  state: LaneVerification;
};

/**
 * Provider catalog availability and freshness.
 */
export type CatalogStatus = "available" | "unavailable" | "stale" | "unknown";

/**
 * Provider-native control category without cross-provider semantics.
 */
export type ControlKind =
  "model_config" | "thought_level" | "service_tier" | "other";

/**
 * What a host's background request on a lane may carry, by the lane's design.
 *
 * How far each is proven on a host is the served catalog's answer, not this
 * one's.
 *
 * Attributes: runnable: Whether the lane runs a background request at all.
 * inputs: The inputs the lane's transport carries in a background request's
 * turn (`text`, `image`, `pdf`), in that order. Empty where the lane is not
 * runnable. On a lane whose models differ, a model must also read the input:
 * see each model's `vision`. options: The reply options the lane honours
 * (`temperature`, `context_tokens`, `response_schema`), in that order. A
 * request naming any other is refused.
 */
export type DeclaredBackground = {
  runnable: boolean;
  inputs: BackgroundInput[];
  options: BackgroundOption[];
};

/**
 * A provider's icon: its key and the drawings bundled for it.
 *
 * Attributes: key: The stable key the artwork is fetched by, at `/v1/provider-
 * icons/{key}/{variant}`. variants: The bundled drawings, in the order a
 * client should prefer them. `mono` is always present.
 */
export type DeclaredIcon = {
  key: string;
  variants: DeclaredIconVariant[];
};

/**
 * Where the bundled icon artwork comes from and the terms it is used under.
 *
 * A client that shows the artwork shows it under these terms.
 *
 * Attributes: title: The artwork source's name as shown to a person. url:
 * Where the source is published. pin: The exact release the artwork was taken
 * from. licence: The licence the drawings are used under. notice: The
 * copyright and permission notice that licence requires. trademarks: The
 * statement that the depicted marks are their holders'.
 */
export type DeclaredIconAttribution = {
  title: string;
  url: string;
  pin: string;
  licence: string;
  notice: string;
  trademarks: string;
};

/**
 * One drawing of a provider's icon that the service bundles.
 *
 * Attributes: variant: `mono`, drawn in `currentColor` so it follows the
 * client's text colour, or `color`, in the brand's own colours. media_type:
 * The artwork's media type. sha256: The SHA-256 of the artwork's bytes, as
 * lowercase hex. The gateway serves the same value as the artwork's entity
 * tag.
 */
export type DeclaredIconVariant = {
  variant: IconVariant;
  media_type: "image/svg+xml";
  sha256: string;
};

/**
 * The licence a model is distributed under, without its text.
 *
 * Attributes: spdx: The SPDX identifier, where the licence text is a
 * recognised standard text; null otherwise. name: The licence's name as shown
 * to a person. digest: `sha256:` and the lowercase hex SHA-256 of the licence
 * text, as the vendor's registry names it.
 */
export type DeclaredLicence = {
  spdx: string | null;
  name: string;
  digest: string;
};

/**
 * One model a lane offers, as the provider publishes it.
 *
 * Attributes: id: The model id a run names, in the vendor's own spelling.
 * display_name: The model's name as shown to a person. effort: Whether the
 * model reasons and which effort levels it accepts on this lane. A model with
 * no effort control is distinct from one whose effort control is unknown.
 * vision: Whether the model accepts images, or null where no source states it.
 * size_bytes: The model's download size in bytes, or null where no source
 * states it. context_length: The model's context length in tokens, or null
 * where no source states it. licence: The licence the model is distributed
 * under, or null where no source states it. The licence text is not part of
 * this document. artefacts: How each local engine obtains the model (what the
 * host fetches), and the context a llama.cpp load of it asks for, or null
 * where no source states it.
 */
export type DeclaredModel = {
  id: string;
  display_name: string;
  effort: EffortCapability;
  vision: boolean | null;
  size_bytes: number | null;
  context_length: number | null;
  licence: DeclaredLicence | null;
  artefacts: ModelArtefacts | null;
};

/**
 * How much reasoning a run asks its model for, lowest first.
 *
 * The ordered union of the values the provider lanes offer. Every lane spells
 * the values it supports with these same strings, so a member's value is also
 * the provider-native value; what differs per lane is which members it accepts
 * and how the value reaches the provider.
 */
export type Effort = "low" | "medium" | "high" | "xhigh" | "max" | "ultra";

/**
 * Whether a model reasons, and the effort levels it accepts on its lane.
 *
 * Attributes: reasoning: Whether the model reasons (`Reasoning`). control:
 * Whether it has effort levels, none, or none are known. levels: The accepted
 * levels, lowest first; empty unless `control` is `levels`. default: The level
 * applied when a run names none, or null when no vendor source states one.
 */
export type EffortCapability = {
  reasoning: Reasoning;
  control: EffortControl;
  levels: Effort[];
  default: Effort | null;
};

/**
 * What a model's sources state about its effort control.
 *
 * Values: LEVELS: It accepts the listed effort levels. NONE: It has no effort
 * control. UNKNOWN: No source states a level set.
 */
export type EffortControl = "levels" | "none" | "unknown";

export type EngineArtefact = RegistryArtefact | HuggingFaceArtefact;

/**
 * Where a person goes to start or repair a local engine.
 */
export type EngineDoor = "local_ai_setup";

/**
 * Why a local engine's server could not be read, as a closed set.
 *
 * Values: NO_ANSWER_IN_TIME: The server accepted the request and did not
 * answer within the read's bound. NOT_REACHABLE: The connection could not be
 * made or was lost. ANSWER_UNREADABLE: The server answered, but not in the
 * shape this engine's server documents.
 */
export type EngineDownReason =
  "no_answer_in_time" | "not_reachable" | "answer_unreadable";

/**
 * Whether a local engine's server runs, with the reason and door when not.
 */
export type EngineHealthResponse = {
  engine: LocalEngine;
  state: EngineState;
  reason?: EngineDownReason | null;
  door?: EngineDoor | null;
};

/**
 * Whether a local engine's server answered the read of it.
 */
export type EngineState = "running" | "not_running";

/**
 * A factual binary health axis whose evidence may still be unknown.
 */
export type HealthState = "available" | "unavailable" | "unknown";

/**
 * Whether a lane has a current turn through the shipped hosted package.
 */
export type HostedCertificationState = "unknown" | "pending" | "proven";

/**
 * A GGUF model, and its projector, at one commit of a Hugging Face repository.
 *
 * Attributes: source: `huggingface`. repository: `<owner>/<repo>`, each a
 * plain name. revision: The full lowercase commit id the files are fetched at;
 * never a branch or tag, so the pinned digests keep describing the bytes.
 * model: The GGUF model file. projector: The projector file the model loads
 * with to read images, or null for a model without one; left out of the
 * document then. It is never the model file itself.
 */
export type HuggingFaceArtefact = {
  source: "huggingface";
  repository: string;
  revision: string;
  model: ArtefactFile;
  projector?: ArtefactFile | null;
};

/**
 * How an icon is drawn.
 *
 * Values: MONO: One colour, `currentColor`, so it follows the client's text.
 * COLOR: The brand's own colours.
 */
export type IconVariant = "mono" | "color";

/**
 * A capability whose proof state a lane discloses. The value is the wire form.
 *
 * Web retrieval is withheld from a lane that has not proven it. Tool access
 * and writing through this service's own tool server are never withheld: each
 * call is put to the person, so their state is disclosed only. Reading an
 * image and reading a PDF cannot be withheld, so their state is a claim only:
 * what the service may say the lane does.
 */
export type LaneCapability =
  | "tool_access"
  | "writing"
  | "web_retrieval"
  | "image_reading"
  | "pdf_reading"
  | "subagents"
  | "subagent_cancel"
  | "subagent_limits";

/**
 * How far a lane, or one capability on it, had been proven on this host.
 *
 * For the lane itself the work is a completed turn; for a capability it is the
 * work that capability's own live test completed.
 */
export type LaneVerification =
  "proven" | "unproven_version" | "unproven" | "not_applicable";

/**
 * A keyless engine whose server runs on this computer.
 */
export type LocalEngine = "llamacpp" | "ollama";

/**
 * How each local engine obtains one model.
 *
 * Each engine's artefact is null where the catalog declares no way to obtain
 * the model for that engine.
 *
 * Attributes: ollama: The registry name the Ollama engine pulls the model as.
 * llamacpp: What the llama.cpp engine fetches: a registry name, whose manifest
 * carries a projector layer where the model reads images, or a Hugging Face
 * model with its projector. llamacpp_default_context: The context size, in
 * tokens, a llama.cpp load of the model asks for, or null where none is
 * declared. It never exceeds the model's context length, and is declared only
 * with a llama.cpp artefact.
 */
export type ModelArtefacts = {
  ollama: RegistryArtefact | null;
  llamacpp: EngineArtefact | null;
  llamacpp_default_context: number | null;
};

/**
 * Whether a lane's models are downloaded to this computer, stamped by the
 * service on every lane.
 */
export type ModelDownload = "required" | "none";

/**
 * The multi-agent runtime a model runs its native subagents on.
 *
 * A lane whose models differ here bounds their subagents differently: on
 * Codex, a `v1` model's children are held to one level by the lane's own
 * configuration, while a `v2` model spawns at any depth whatever it says.
 *
 * Values: DISABLED: The model runs no native subagents. V1: The first runtime,
 * whose depth the lane's configuration bounds. V2: The second runtime, whose
 * depth no configuration bounds.
 */
export type MultiAgentGeneration = "disabled" | "v1" | "v2";

/**
 * A provider's public pages and endpoints.
 *
 * Attributes: docs_url: The vendor documentation the lanes were configured
 * from. models_url: The vendor's model-list endpoint, where one is published.
 * status: Where the vendor publishes its service status.
 */
export type PlatformUrls = {
  docs_url: string | null;
  models_url: string | null;
  status: StatusSource;
};

/**
 * Canonical product identities shared by requests and configuration.
 */
export type Provider =
  | "claude"
  | "codex"
  | "antigravity"
  | "kimi"
  | "zai"
  | "zhipu"
  | "deepseek"
  | "moonshot"
  | "minimax"
  | "qwen"
  | "ollama"
  | "llamacpp";

export type ProviderCatalogStateResponse = {
  status: CatalogStatus;
  checked_at: string;
  revision?: string | null;
  expires_at?: string | null;
  reason?: string | null;
};

export type ProviderHealthResponse = {
  configured: HealthState;
  transport: HealthState;
  authentication: AuthenticationState;
  catalog: CatalogStatus;
  admission: AdmissionState;
  selectable: boolean;
  reasons?: string[];
  checked_at: string;
  engine?: EngineHealthResponse | null;
};

export type ProviderNativeControlOptionResponse = {
  option_id: string;
  display_name: string;
  description?: string | null;
};

export type ProviderNativeControlResponse = {
  control_id: string;
  kind: ControlKind;
  display_name: string;
  options?: ProviderNativeControlOptionResponse[];
  default_option_id?: string | null;
  description?: string | null;
};

/**
 * How a run reaches a named provider product.
 */
export type ProviderTransport = "api" | "cli";

/**
 * Whether a model reasons or thinks before it answers.
 *
 * Values: SUPPORTED: It reasons; its sources state no on-off control.
 * ALWAYS_ON: It always reasons and cannot be told not to. TOGGLE: Reasoning
 * can be switched on and off. UNSUPPORTED: It does not reason. UNKNOWN: No
 * source states it.
 */
export type Reasoning =
  "supported" | "always_on" | "toggle" | "unsupported" | "unknown";

/**
 * A model the Ollama model registry serves.
 *
 * Attributes: source: `registry`. name: The name the registry serves the model
 * under, `[[host/]namespace/]model[:tag]`.
 */
export type RegistryArtefact = {
  source: "registry";
  name: string;
};

/**
 * A provider catalog answer: the running agent's catalog, or the one it
 * declares.
 */
export type ServedCatalogAnswer =
  ServedProviderCatalog | ServedDeclaredProviderCatalog;

/**
 * One model of a lane as the service relays it: `installed` is left out on a
 * hosted lane, which downloads nothing, and on a local lane whose server
 * nobody read.
 */
export type ServedCatalogModel = {
  entry_id: string;
  model: string;
  display_name: string;
  description?: string | null;
  capabilities?: string[];
  native_control_ids?: string[];
  efforts?: Effort[];
  default_effort?: Effort | null;
  multi_agent_generation?: MultiAgentGeneration | null;
  vision: boolean | null;
  size_bytes: number | null;
  context_length: number | null;
  licence: DeclaredLicence | null;
  llamacpp_default_context: number | null;
  installed?: boolean;
};

/**
 * The catalog the agent declares before it runs, as the service relays it.
 */
export type ServedDeclaredCatalogDocument = {
  schema_version?: 7;
  providers: ServedDeclaredLane[];
  icon_attribution: DeclaredIconAttribution;
};

/**
 * One lane the agent declares, as the service relays it: stamped with whether
 * its models are downloaded to this computer.
 */
export type ServedDeclaredLane = {
  id: string;
  provider: string;
  transport: ProviderTransport;
  display_name: string;
  description: string;
  auth_kind: AuthKind;
  logout?: boolean;
  default_base_url: string | null;
  agent_credential_id: string | null;
  reads_off_host: boolean;
  cli_programs: string[];
  icon: DeclaredIcon | null;
  platform: PlatformUrls;
  default_model: string | null;
  models: DeclaredModel[];
  recommended: { [key: string]: string };
  background: DeclaredBackground;
  unread: UnreadSource[];
  model_download: ModelDownload;
};

/**
 * The catalog the agent declares, in the envelope that tells it from a running
 * agent's.
 */
export type ServedDeclaredProviderCatalog = {
  kind: "declared";
  catalog: ServedDeclaredCatalogDocument;
};

/**
 * A lane's model catalog as the service relays it.
 */
export type ServedLaneCatalog = {
  schema_version?: 2;
  state: ProviderCatalogStateResponse;
  recommended_entry_id?: string | null;
  recommended?: { [key: string]: string };
  models?: ServedCatalogModel[];
  native_controls?: ProviderNativeControlResponse[];
};

/**
 * The running agent's provider catalog as the service relays it.
 */
export type ServedProviderCatalog = {
  api_version?: "v1";
  providers?: ServedProviderLane[];
};

/**
 * One provider lane as the service relays it: the agent's lane, stamped with
 * whether its models are downloaded to this computer.
 */
export type ServedProviderLane = {
  provider_id: Provider;
  transport: ProviderTransport;
  display_name: string;
  auth_kind: AuthKind;
  execution_mode: string;
  executable: boolean;
  model_source: "catalog" | "declared";
  health: ProviderHealthResponse;
  catalog: ServedLaneCatalog;
  hosted_certification?: HostedCertificationState;
  capability_proofs?: CapabilityProof[];
  background_requests: BackgroundRequestSupportResponse;
  model_download: ModelDownload;
};

/**
 * How a provider publishes its service status, which selects its reader.
 *
 * Values: STATUSPAGE_V2: A statuspage-style JSON API with components. RSS: An
 * incident feed, which states no component state. NONE: Nothing machine-
 * readable; status is always unknown.
 */
export type StatusKind = "statuspage_v2" | "rss" | "none";

/**
 * Where a provider publishes its service status.
 *
 * Attributes: kind: How it is published, which selects the reader. page_url:
 * The page a person reads, or null where there is none. api_url: The machine-
 * readable endpoint the reader polls; null exactly when `kind` is `none`.
 */
export type StatusSource = {
  kind: StatusKind;
  page_url: string | null;
  api_url: string | null;
};

/**
 * A source the compile meant to read for a lane and did not.
 *
 * A lane whose vendor listing was not read is served from the next source in
 * precedence, and this record says so, so the lane is never mistaken for one
 * the vendor's own listing answered for.
 *
 * Attributes: source: The id of the unread source in the document's sources.
 * reason: Why it was not read. It names a setting, never a credential value.
 */
export type UnreadSource = {
  source: string;
  reason: string;
};
